   &curl.changelog.share-handle-param;

  &reftitle.examples;



    Esempio di curl_share_setopt


     Questo esempio crea un gestore di condivisione cURL, vi aggiunge due gestori
     cURL e poi li esegue condividendo i dati dei cookie.



<?php
// Crea il gestore di condivisione cURL e lo imposta per condividere i dati dei cookie
$sh = curl_share_init();
curl_share_setopt($sh, CURLSHOPT_SHARE, CURL_LOCK_DATA_COOKIE);

// Inizializza il primo gestore cURL e gli assegna il gestore di condivisione
$ch1 = curl_init("http://example.com/");
curl_setopt($ch1, CURLOPT_SHARE, $sh);

// Esegue il primo gestore cURL
curl_exec($ch1);

// Inizializza il secondo gestore cURL e gli assegna il gestore di condivisione
$ch2 = curl_init("http://php.net/");
curl_setopt($ch2, CURLOPT_SHARE, $sh);

// Esegue il secondo gestore cURL
//  tutti i cookie del gestore $ch1 sono condivisi con il gestore $ch2
curl_exec($ch2);

// Chiude il gestore di condivisione cURL
curl_share_close($sh);
?>
